python3 -I - <<'EOF'
import re,glob
seen=set()
for f in glob.glob('*.jsonl'):
    s=open(f,errors='ignore').read()
    for pat in [r'hl\.plugin\.overview', r'[Hh]yprspace']:
        for m in re.finditer(pat,s):
            t=s[max(0,m.start()-300):m.end()+400].replace('\\n','\n')
            k=t[250:420]
            if k in seen: continue
            seen.add(k)
            if len(seen)<10: print('=====',f[:8]); print(t)
EOF

