python3 -I - <<'EOF'
import re,glob
seen=set()
for f in glob.glob('*.jsonl'):
    s=open(f,errors='ignore').read()
    for m in re.finditer(r'sudo dnf (install|remove)[^"\\`]{0,250}',s):
        t=m.group(0)
        if t not in seen: seen.add(t); print(t)
EOF
